def dp_memo(n, memo={}):
    if n in memo:
        return memo[n]
    if base_case(n):
        return base_value
    memo[n] = recurrence_relation(n)
    return memo[n]

bottom_up_tabulation.template:
def dp_tabulation(n):
    dp = [0] * (n + 1)
    dp[0] = base_value
    for i in range(1, n + 1):
        dp[i] = recurrence_relation(i, dp)
    return dp[n]

