def solve_1d_optimized(n):
    if n <= 1:
        return base_cases[n]

    prev2, prev1 = base_cases[0], base_cases[1]

    for i in range(2, n + 1):
        current = recurrence_relation(prev1, prev2)
        prev2, prev1 = prev1, current

    return prev1

