def solve_2d_dp(m, n):
    # Initialize DP table
    dp = [[0] * n for _ in range(m)]

    # Base cases
    for i in range(m):
        dp[i][0] = base_value_col
    for j in range(n):
        dp[0][j] = base_value_row

    # Fill DP table
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = recurrence_relation(dp, i, j)

    return dp[m-1][n-1]
